<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class AdministrationController extends Controller{
private function ok(Request $r,$manage=false){$u=$r->user();abort_unless($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('director')||$u->hasRole('deputy_director')||$u->canDo($manage?'management.manage':'management.view'),403);}
public function index(Request $r){$this->ok($r);$p=$r->attributes->get('academic_period');$pid=$p->id;$uid=$r->user()->id;$roles=$r->user()->roles()->pluck('code')->all();
$docs=DB::table('document_routes as dr')->join('official_documents as d','d.id','=','dr.official_document_id')->where('dr.status','active')->where(function($q)use($uid,$roles){$q->where('dr.assignee_user_id',$uid);if($roles)$q->orWhereIn('dr.assignee_role',$roles);})->select('d.id','d.number','d.title','d.due_on','dr.action','dr.due_on as route_due')->orderBy('dr.due_on')->limit(15)->get();
$sign=DB::table('official_documents')->where('status','approved')->orderBy('due_on')->limit(15)->get();
$overdueTasks=DB::table('management_tasks as t')->join('users as u','u.id','=','t.assigned_to')->whereNotIn('t.status',['done','cancelled'])->where('t.due_on','<',date('Y-m-d'))->select('t.*','u.name as assignee_name')->orderBy('t.due_on')->limit(20)->get();
$docTasks=DB::table('document_tasks')->whereNotIn('status',['done','cancelled'])->where('due_on','<',date('Y-m-d'))->count();
$qualityRisks=DB::table('quality_risks')->where(['academic_period_id'=>$pid,'status'=>'open'])->whereRaw('probability*impact>=12')->count();
$qualityFindings=DB::table('quality_findings as f')->join('quality_audits as a','a.id','=','f.quality_audit_id')->where('a.academic_period_id',$pid)->where('f.status','open')->whereIn('f.severity',['major','critical'])->count();
$requests=DB::table('service_requests')->whereNotIn('status',['resolved','closed','cancelled'])->count();$requestsOverdue=DB::table('service_requests')->whereNotIn('status',['resolved','closed','cancelled'])->where('due_at','<',now())->count();
$facility=DB::table('facility_work_orders')->whereNotIn('status',['completed','cancelled'])->count();$facilityCritical=DB::table('facility_work_orders')->whereNotIn('status',['completed','cancelled'])->where(fn($q)=>$q->where('priority','urgent')->orWhere('due_at','<',now()))->count();
$debts=DB::table('semester_results')->where('academic_period_id',$pid)->whereIn(DB::raw('LOWER(value)'),['2','незачет','незачёт','не зачтено'])->count();
$practice=DB::table('practice_placements')->where('academic_period_id',$pid)->where('ends_on','<',date('Y-m-d'))->whereNotIn('status',['completed','failed'])->count();
$methodical=DB::table('teaching_load_plans as l')->leftJoin('curriculum_plans as cp',function($j)use($pid){$j->on('cp.study_group_id','=','l.study_group_id')->on('cp.subject_id','=','l.subject_id')->on('cp.teacher_id','=','l.teacher_id')->where('cp.academic_period_id',$pid);})->where('l.academic_period_id',$pid)->whereNull('cp.id')->count();
$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();foreach($groups as $g){$a=DB::table('attendance_records as ar')->join('lesson_occurrences as l','l.id','=','ar.lesson_occurrence_id')->where(['l.academic_period_id'=>$pid,'l.study_group_id'=>$g->id]);$n=(clone $a)->count();$g->attendance=$n?round((clone $a)->whereIn('ar.status',['present','late'])->count()*100/$n,1):null;$gr=DB::table('grade_records as gr')->join('lesson_occurrences as l','l.id','=','gr.lesson_occurrence_id')->where(['l.academic_period_id'=>$pid,'l.study_group_id'=>$g->id])->whereIn('gr.value',['2','3','4','5']);$g->avg=round((float)$gr->avg(DB::raw('CAST(gr.value AS REAL)')),2);}$problemGroups=$groups->filter(fn($g)=>($g->attendance!==null&&$g->attendance<80)||($g->avg>0&&$g->avg<3.5))->take(10);
$recentDocs=DB::table('official_documents')->whereDate('created_at',date('Y-m-d'))->orderByDesc('id')->limit(10)->get();
return view('administration.index',compact('p','docs','sign','overdueTasks','docTasks','qualityRisks','qualityFindings','requests','requestsOverdue','facility','facilityCritical','debts','practice','methodical','problemGroups','recentDocs'));}
public function tasks(Request $r){$this->ok($r);$q=DB::table('management_tasks as t')->join('users as u','u.id','=','t.assigned_to')->join('users as c','c.id','=','t.created_by')->select('t.*','u.name as assignee_name','c.name as creator_name');if(!$r->user()->canDo('management.manage')&&!$r->user()->hasRole('director')&&!$r->user()->isSuperAdmin())$q->where(fn($z)=>$z->where('t.assigned_to',$r->user()->id)->orWhere('t.created_by',$r->user()->id));$rows=$q->orderByRaw("CASE WHEN t.status IN ('done','cancelled') THEN 1 ELSE 0 END")->orderBy('t.due_on')->get();$users=DB::table('users')->orderBy('name')->get();return view('administration.tasks',compact('rows','users'));}
public function taskStore(Request $r){$this->ok($r,true);$d=$r->validate(['title'=>'required|string|max:500','instruction'=>'nullable|string|max:10000','area'=>'required|string|max:100','priority'=>'required|in:low,normal,high,critical','assigned_to'=>'required|exists:users,id','due_on'=>'nullable|date']);DB::table('management_tasks')->insert($d+['created_by'=>$r->user()->id,'status'=>'new','created_at'=>now(),'updated_at'=>now()]);return back();}
public function taskUpdate(Request $r,$id){$this->ok($r);$x=DB::table('management_tasks')->find($id);abort_if(!$x,404);abort_unless($x->assigned_to===$r->user()->id||$x->created_by===$r->user()->id||$r->user()->isSuperAdmin()||$r->user()->hasRole('director')||$r->user()->canDo('management.manage'),403);$d=$r->validate(['status'=>'required|in:new,in_progress,waiting,done,cancelled','result'=>'nullable|string|max:10000']);$up=$d+['updated_at'=>now()];if($d['status']==='done')$up['completed_at']=now();DB::table('management_tasks')->where('id',$id)->update($up);return back();}
}